"""Bounded reads for owner-only local authority files."""

from __future__ import annotations

import os
import stat
from pathlib import Path


def private_regular_file_is_valid(
    path: Path,
    *,
    require_private_parent: bool = False,
) -> bool:
    """Return whether a path names an owner-only regular file.

    Parent validation is optional because some legacy authority files live in a
    user-owned directory whose privacy is established elsewhere.
    """

    try:
        parent_metadata = path.parent.lstat() if require_private_parent else None
        metadata = path.lstat()
    except OSError:
        return False
    if parent_metadata is not None and not _private_directory_metadata_is_valid(parent_metadata):
        return False
    return _private_file_metadata_is_valid(metadata)


def read_private_regular_bytes(
    path: Path,
    *,
    max_bytes: int,
    require_private_parent: bool = False,
) -> bytes | None:
    """Read a private regular file through one bounded, no-follow descriptor."""

    if type(max_bytes) is not int or max_bytes < 1:
        raise ValueError("max_bytes must be a positive integer")
    try:
        parent_before = path.parent.lstat() if require_private_parent else None
        path_before = path.lstat()
    except OSError:
        return None
    if parent_before is not None and not _private_directory_metadata_is_valid(parent_before):
        return None
    if not _private_file_metadata_is_valid(path_before):
        return None

    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
    try:
        if os.name == "nt":
            from .windows_replaceable_file import open_replaceable_read_descriptor

            descriptor = open_replaceable_read_descriptor(path, flags)
        else:
            descriptor = os.open(path, flags)
    except OSError:
        return None
    try:
        opened = os.fstat(descriptor)
        if not _private_file_metadata_is_valid(opened) or not _same_file(
            path_before,
            opened,
        ):
            return None
        if opened.st_size > max_bytes:
            return None
        chunks: list[bytes] = []
        consumed = 0
        while consumed < max_bytes:
            chunk = os.read(
                descriptor,
                min(64 * 1024, max_bytes - consumed),
            )
            if not chunk:
                break
            chunks.append(chunk)
            consumed += len(chunk)
        closed_state = os.fstat(descriptor)
        if not _stable_file_metadata(opened, closed_state):
            return None
    finally:
        os.close(descriptor)

    if require_private_parent:
        try:
            parent_after = path.parent.lstat()
        except OSError:
            return None
        if parent_before is None or not _stable_directory_metadata(
            parent_before,
            parent_after,
        ):
            return None
    return b"".join(chunks)


def read_private_regular_text(
    path: Path,
    *,
    max_bytes: int,
    require_private_parent: bool = False,
) -> str | None:
    """Read bounded UTF-8 text from a private regular file."""

    payload = read_private_regular_bytes(
        path,
        max_bytes=max_bytes,
        require_private_parent=require_private_parent,
    )
    if payload is None:
        return None
    try:
        return payload.decode("utf-8").strip()
    except UnicodeDecodeError:
        return None


def _private_file_metadata_is_valid(metadata: os.stat_result) -> bool:
    if stat.S_ISLNK(metadata.st_mode) or not stat.S_ISREG(metadata.st_mode):
        return False
    if os.name == "nt":
        return True
    return metadata.st_uid == os.getuid() and not stat.S_IMODE(metadata.st_mode) & 0o077


def _private_directory_metadata_is_valid(metadata: os.stat_result) -> bool:
    if not stat.S_ISDIR(metadata.st_mode):
        return False
    if os.name == "nt":
        return True
    return metadata.st_uid == os.getuid() and not stat.S_IMODE(metadata.st_mode) & 0o077


def _same_file(left: os.stat_result, right: os.stat_result) -> bool:
    return left.st_dev == right.st_dev and left.st_ino == right.st_ino


def _stable_file_metadata(
    before: os.stat_result,
    after: os.stat_result,
) -> bool:
    return (
        _same_file(before, after)
        and before.st_mode == after.st_mode
        and before.st_size == after.st_size
        and before.st_mtime_ns == after.st_mtime_ns
        and before.st_ctime_ns == after.st_ctime_ns
    )


def _stable_directory_metadata(
    before: os.stat_result,
    after: os.stat_result,
) -> bool:
    """Confirm the parent directory was not replaced or made non-private.

    Sibling writes update directory mtime/ctime, so those timestamps are not
    part of the identity check.
    """

    return _private_directory_metadata_is_valid(after) and _same_file(before, after) and before.st_mode == after.st_mode


__all__ = [
    "private_regular_file_is_valid",
    "read_private_regular_bytes",
    "read_private_regular_text",
]

"""Authenticated transport primitives for the Codex daemon hook bridge."""

from __future__ import annotations

import hashlib
import hmac
import http.client
import json
import os
import secrets
import stat
import time
from collections.abc import Mapping
from pathlib import Path
from urllib.parse import urlparse

_LOOPBACK_HOSTS = frozenset({"127.0.0.1", "localhost", "::1"})
_DISCOVERY_PROTOCOL_VERSION = 1
_DISCOVERY_CHALLENGE_TTL_SECONDS = 5
_MAX_DAEMON_RESPONSE_BYTES = 1_000_000
_MINIMUM_OPERATION_SECONDS = 0.01


class _DaemonResponseError(ValueError):
    def __init__(self, status: int, detail: str, *, authenticated: bool) -> None:
        super().__init__(f"daemon returned HTTP {status}")
        self.status = status
        self.detail = detail
        self.authenticated = authenticated


def _assert_loopback_http_url(url: str) -> None:
    parsed = urlparse(url)
    if parsed.scheme != "http":
        raise ValueError(f"daemon URL must use http, not {parsed.scheme!r}")
    if parsed.username is not None or parsed.password is not None:
        raise ValueError("daemon URL must not contain credentials")
    host = (parsed.hostname or "").lower()
    if host not in _LOOPBACK_HOSTS:
        raise ValueError(f"daemon URL must target loopback, not {host!r}")
    if parsed.port is None:
        raise ValueError("daemon URL must include an explicit port")


def _json_object(text: str) -> dict[str, object] | None:
    try:
        payload = json.loads(text)
    except json.JSONDecodeError:
        return None
    return payload if isinstance(payload, dict) else None


def _private_file_text(path: Path, *, label: str) -> str:
    try:
        parent_metadata = path.parent.lstat()
        metadata = path.lstat()
    except OSError as error:
        raise ValueError(f"{label} is unavailable") from error
    if not stat.S_ISDIR(parent_metadata.st_mode):
        raise ValueError("Guard home is not a directory")
    if stat.S_ISLNK(metadata.st_mode) or not stat.S_ISREG(metadata.st_mode):
        raise ValueError(f"{label} must be a regular file")
    if os.name != "nt":
        if parent_metadata.st_uid != os.getuid() or metadata.st_uid != os.getuid():
            raise ValueError(f"{label} ownership does not match the current user")
        if stat.S_IMODE(parent_metadata.st_mode) & 0o077 or stat.S_IMODE(metadata.st_mode) & 0o077:
            raise ValueError(f"{label} permissions are not owner-only")
    try:
        if os.name == "nt":
            from ..windows_replaceable_file import read_replaceable_text

            return read_replaceable_text(path).strip()
        return path.read_text(encoding="utf-8").strip()
    except OSError as error:
        raise ValueError(f"{label} is unreadable") from error


def _canonical_discovery_payload(payload: dict[str, object]) -> bytes:
    return json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=True).encode("utf-8")


def _sign_discovery_payload(discovery_key: str, payload: dict[str, object]) -> str:
    try:
        key = bytes.fromhex(discovery_key)
    except ValueError as error:
        raise ValueError("daemon discovery key is malformed") from error
    if len(key) != 32:
        raise ValueError("daemon discovery key is malformed")
    return hmac.new(key, _canonical_discovery_payload(payload), hashlib.sha256).hexdigest()


def _authenticated_state(state_path: str | Path) -> tuple[dict[str, object], str]:
    path = Path(state_path)
    discovery_key = _private_file_text(path.parent / "daemon-discovery-key", label="daemon discovery key")
    try:
        payload = json.loads(_private_file_text(path, label="daemon state"))
    except json.JSONDecodeError as error:
        raise ValueError("daemon state is malformed") from error
    if not isinstance(payload, dict):
        raise ValueError("daemon state must be a JSON object")
    signature = payload.get("state_signature")
    unsigned = {key: value for key, value in payload.items() if key != "state_signature"}
    try:
        expected_key_id = hashlib.sha256(bytes.fromhex(discovery_key)).hexdigest()
    except ValueError as error:
        raise ValueError("daemon discovery key is malformed") from error
    if (
        not isinstance(signature, str)
        or unsigned.get("discovery_protocol_version") != _DISCOVERY_PROTOCOL_VERSION
        or unsigned.get("discovery_key_id") != expected_key_id
        or not secrets.compare_digest(signature, _sign_discovery_payload(discovery_key, unsigned))
    ):
        raise ValueError("daemon state authentication failed")
    host = unsigned.get("host")
    port = unsigned.get("port")
    pid = unsigned.get("pid")
    state_id = unsigned.get("state_id")
    started_at = unsigned.get("started_at")
    guard_home = unsigned.get("guard_home")
    auth_token_id = unsigned.get("auth_token_id")
    if (
        not isinstance(host, str)
        or host.lower() not in _LOOPBACK_HOSTS
        or not isinstance(port, int)
        or not 0 < port <= 65535
        or not isinstance(pid, int)
        or pid <= 0
        or not isinstance(state_id, str)
        or not state_id
        or not isinstance(started_at, str)
        or not started_at
        or not isinstance(guard_home, str)
        or not isinstance(auth_token_id, str)
    ):
        raise ValueError("daemon state identity is incomplete")
    try:
        expected_guard_home = str(path.parent.resolve())
        state_guard_home = str(Path(guard_home).resolve())
    except OSError as error:
        raise ValueError("daemon state Guard home is invalid") from error
    if state_guard_home != expected_guard_home:
        raise ValueError("daemon state belongs to a different Guard home")
    return payload, discovery_key


def _daemon_url(state_path: str | Path) -> str:
    payload, _discovery_key = _authenticated_state(state_path)
    host = str(payload["host"])
    port = payload.get("port")
    rendered_host = f"[{host}]" if ":" in host else host
    return f"http://{rendered_host}:{port}"


def _daemon_auth_token(state_path: str | Path, state: Mapping[str, object]) -> str:
    path = Path(state_path)
    token = _private_file_text(path.parent / "daemon-auth-token", label="daemon auth token")
    expected_token_id = state.get("auth_token_id")
    actual_token_id = hashlib.sha256(token.encode("utf-8")).hexdigest()
    if (
        not token
        or not isinstance(expected_token_id, str)
        or not secrets.compare_digest(actual_token_id, expected_token_id)
    ):
        raise ValueError("daemon auth token does not match authenticated state")
    return token


def _http_json_response(
    response: http.client.HTTPResponse,
    *,
    label: str,
    connection: http.client.HTTPConnection,
    deadline: float,
    authenticated: bool,
) -> dict[str, object]:
    body = bytearray()
    while len(body) <= _MAX_DAEMON_RESPONSE_BYTES:
        remaining = _remaining_seconds(deadline)
        if remaining < _MINIMUM_OPERATION_SECONDS:
            raise TimeoutError(f"{label} exceeded the hook deadline")
        if connection.sock is not None:
            connection.sock.settimeout(remaining)
        chunk = response.read1(min(64 * 1024, _MAX_DAEMON_RESPONSE_BYTES + 1 - len(body)))
        if not chunk:
            break
        body.extend(chunk)
    if len(body) > _MAX_DAEMON_RESPONSE_BYTES:
        raise ValueError(f"{label} response is too large")
    if response.status != 200:
        raise _DaemonResponseError(
            response.status,
            body.decode("utf-8", errors="replace").strip(),
            authenticated=authenticated,
        )
    payload = _json_object(bytes(body).decode("utf-8", errors="replace").strip())
    if payload is None:
        raise ValueError(f"{label} returned malformed JSON")
    return payload


def _verify_challenge_response(
    response: dict[str, object],
    *,
    state: Mapping[str, object],
    discovery_key: str,
    nonce: str,
    hook_event: str,
) -> str:
    proof = response.get("proof")
    unsigned = {key: value for key, value in response.items() if key != "proof"}
    expected_fields = {
        "protocol_version": _DISCOVERY_PROTOCOL_VERSION,
        "nonce": nonce,
        "state_id": state.get("state_id"),
        "host": state.get("host"),
        "port": state.get("port"),
        "pid": state.get("pid"),
        "started_at": state.get("started_at"),
        "guard_home": state.get("guard_home"),
        "hook_event": hook_event,
    }
    if any(unsigned.get(key) != value for key, value in expected_fields.items()):
        raise ValueError("daemon identity challenge did not match authenticated state")
    issued_at_ms = unsigned.get("issued_at_ms")
    expires_at_ms = unsigned.get("expires_at_ms")
    now_ms = int(time.time() * 1000)
    if (
        not isinstance(issued_at_ms, int)
        or not isinstance(expires_at_ms, int)
        or issued_at_ms > now_ms + 1000
        or expires_at_ms < now_ms
        or expires_at_ms - issued_at_ms > _DISCOVERY_CHALLENGE_TTL_SECONDS * 1000
    ):
        raise ValueError("daemon identity challenge expired")
    expected_proof = _sign_discovery_payload(discovery_key, unsigned)
    if not isinstance(proof, str) or not secrets.compare_digest(proof, expected_proof):
        raise ValueError("daemon identity challenge authentication failed")
    return proof


def _remaining_seconds(deadline: float, *, cap: float | None = None) -> float:
    remaining = max(0.0, deadline - time.monotonic())
    return remaining if cap is None else min(remaining, cap)

"""Guard daemon pending launch helpers; shared dependencies remain on manager."""

from __future__ import annotations

from . import manager as _manager


def _pending_launch_path(guard_home: _manager.Path) -> _manager.Path:
    return guard_home / _manager._GUARD_DAEMON_PENDING_LAUNCH_FILE


def _record_guard_daemon_pending_launch(
    guard_home: _manager.Path,
    *,
    process: _manager.subprocess.Popen[bytes],
    port: int,
) -> int | None:
    """Persist a Windows PID identity before a detached daemon may escape its parent."""

    if _manager.os.name != "nt":
        return None
    creation_time = _manager.windows_process_creation_time(process.pid)
    if creation_time is None:
        raise RuntimeError("Guard daemon process identity could not be recorded.")
    _manager._ensure_private_directory(guard_home)
    with _manager._guard_daemon_state_write_lock(guard_home):
        discovery_key = _manager.ensure_daemon_discovery_key(guard_home)
        pending = _manager.authenticate_daemon_state(
            {
                "state_kind": "daemon_launch_pending",
                "guard_home": str(guard_home.resolve()),
                "pid": process.pid,
                "port": port,
                "process_creation_time": creation_time,
            },
            discovery_key=discovery_key,
        )
        _manager._write_private_atomic_text(
            _manager._pending_launch_path(guard_home),
            _manager.json.dumps(pending, sort_keys=True),
        )
    return creation_time


def load_authenticated_guard_daemon_pending_launch(guard_home: _manager.Path) -> dict[str, object] | None:
    """Load one signed pending-launch PID identity from a private regular file."""

    if _manager.os.name != "nt":
        return None
    raw_payload = _manager.read_private_regular_text(
        _manager._pending_launch_path(guard_home),
        max_bytes=_manager._GUARD_DAEMON_PENDING_LAUNCH_MAX_BYTES,
        require_private_parent=True,
    )
    if raw_payload is None:
        return None
    try:
        payload = _manager.json.loads(raw_payload)
    except _manager.json.JSONDecodeError:
        return None
    discovery_key = _manager.load_daemon_discovery_key(guard_home)
    if (
        discovery_key is None
        or not isinstance(payload, dict)
        or not _manager.verify_daemon_state(payload, discovery_key=discovery_key)
        or payload.get("state_kind") != "daemon_launch_pending"
    ):
        return None
    pid = payload.get("pid")
    port = payload.get("port")
    creation_time = payload.get("process_creation_time")
    payload_guard_home = payload.get("guard_home")
    if (
        type(pid) is not int
        or pid <= 0
        or type(port) is not int
        or not 0 < port <= 65535
        or type(creation_time) is not int
        or creation_time <= 0
        or not isinstance(payload_guard_home, str)
    ):
        return None
    try:
        if _manager.Path(payload_guard_home).resolve() != guard_home.resolve():
            return None
    except OSError:
        return None
    return payload


def _clear_guard_daemon_pending_launch_if_current(
    guard_home: _manager.Path,
    *,
    pid: int,
    creation_time: int | None,
) -> bool:
    if _manager.os.name != "nt" or creation_time is None:
        return True
    with _manager._guard_daemon_state_write_lock(guard_home):
        pending = _manager.load_authenticated_guard_daemon_pending_launch(guard_home)
        if pending is None or pending.get("pid") != pid or pending.get("process_creation_time") != creation_time:
            return False
        _manager._write_private_atomic_text(_manager._pending_launch_path(guard_home), "{}")
        return True


def _clear_spawned_guard_daemon_pending_launch(
    guard_home: _manager.Path,
    *,
    process: _manager.subprocess.Popen[bytes],
    creation_time: int | None,
) -> bool:
    if creation_time is None:
        return True
    return _manager._clear_guard_daemon_pending_launch_if_current(
        guard_home,
        pid=process.pid,
        creation_time=creation_time,
    )


def _guard_daemon_pending_launch_is_active(guard_home: _manager.Path) -> bool:
    pending = _manager.load_authenticated_guard_daemon_pending_launch(guard_home)
    if pending is None:
        return False
    pid = pending.get("pid")
    creation_time = pending.get("process_creation_time")
    if type(pid) is not int or type(creation_time) is not int:
        return False
    actual_creation_time = _manager.windows_process_creation_time(pid)
    if actual_creation_time != creation_time:
        if actual_creation_time is not None or not _manager._guard_daemon_pid_is_running(pid):
            _manager._clear_guard_daemon_pending_launch_if_current(
                guard_home,
                pid=pid,
                creation_time=creation_time,
            )
        return False
    return _manager._guard_daemon_pid_is_running(pid)


def _guard_daemon_pending_launch_state_is_resolved(guard_home: _manager.Path) -> bool:
    if _manager.os.name != "nt":
        return True
    path = _manager._pending_launch_path(guard_home)
    if not path.is_file():
        return True
    pending = _manager.load_authenticated_guard_daemon_pending_launch(guard_home)
    if pending is not None:
        if _manager._guard_daemon_pending_launch_is_active(guard_home):
            return False
        pending = _manager.load_authenticated_guard_daemon_pending_launch(guard_home)
        if pending is not None:
            return False
    return _manager._daemon_lifecycle_artifact_is_exact_tombstone(path)


def _auth_token_path(guard_home: _manager.Path) -> _manager.Path:
    return guard_home / "daemon-auth-token"


def _private_daemon_file_is_valid(path: _manager.Path) -> bool:
    return _manager.private_regular_file_is_valid(path, require_private_parent=True)


def _remove_invalid_daemon_discovery_key(guard_home: _manager.Path) -> bool:
    if _manager.load_daemon_discovery_key(guard_home) is not None:
        return False
    key_path = _manager.daemon_discovery_key_path(guard_home)
    try:
        key_path.unlink()
    except FileNotFoundError:
        return False
    return True


def _ensure_private_directory(path: _manager.Path) -> None:
    path.mkdir(parents=True, exist_ok=True)
    _manager._set_private_mode(path, _manager._GUARD_DAEMON_PRIVATE_DIR_MODE)


def _write_private_text(path: _manager.Path, text: str) -> None:
    descriptor = _manager.os.open(
        path, _manager.os.O_WRONLY | _manager.os.O_CREAT | _manager.os.O_TRUNC, _manager._GUARD_DAEMON_PRIVATE_FILE_MODE
    )
    if _manager.os.name != "nt" and hasattr(_manager.os, "fchmod"):
        with _manager.suppress(OSError):
            _manager.os.fchmod(descriptor, _manager._GUARD_DAEMON_PRIVATE_FILE_MODE)
    with _manager.os.fdopen(descriptor, "w", encoding="utf-8") as handle:
        handle.write(text)
    _manager._set_private_mode(path, _manager._GUARD_DAEMON_PRIVATE_FILE_MODE)


def _write_private_atomic_text(path: _manager.Path, text: str) -> None:
    descriptor, temporary_name = _manager.tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
    temporary_path = _manager.Path(temporary_name)
    try:
        if _manager.os.name != "nt" and hasattr(_manager.os, "fchmod"):
            _manager.os.fchmod(descriptor, _manager._GUARD_DAEMON_PRIVATE_FILE_MODE)
        with _manager.os.fdopen(descriptor, "w", encoding="utf-8", closefd=False) as handle:
            handle.write(text)
            handle.flush()
            _manager.os.fsync(handle.fileno())
        _manager.os.close(descriptor)
        descriptor = -1
        _manager.os.replace(temporary_path, path)
        _manager._set_private_mode(path, _manager._GUARD_DAEMON_PRIVATE_FILE_MODE)
    finally:
        if descriptor >= 0:
            _manager.os.close(descriptor)
        with _manager.suppress(OSError):
            temporary_path.unlink()


def _set_private_mode(path: _manager.Path, mode: int) -> None:
    if _manager.os.name == "nt":
        return
    try:
        _manager.os.chmod(path, mode)
    except OSError:
        return

"""Bounded child for the separate Windows Ex22 rename API probe."""

from __future__ import annotations

import argparse
import ctypes
import json
import os
import sys
from pathlib import Path
from typing import Any, cast


class _NativeCalls:
    def __init__(self, api: Any):
        self.api = api
        self.handles: set[int] = set()
        self.opens = 0
        self.closes = 0
        self.rename_calls = 0
        self.rename_returned = False
        self.first_failed_operation: str | None = None

    def __getattr__(self, name: str) -> Any:
        methods = {
            "CreateFileW": self.create_file,
            "SetFileInformationByHandle": self.rename,
            "CloseHandle": self.close_handle,
        }
        if name in methods:
            return methods[name]
        return getattr(self.api, name)

    def create_file(self, *arguments: Any) -> Any:
        self.opens += 1
        handle = self.api.CreateFileW(*arguments)
        if handle in (None, ctypes.c_void_p(-1).value):
            self.failed("source_open" if arguments[1] & 0x10000 else "parent_open")
        else:
            self.handles.add(int(handle))
        return handle

    def rename(self, *arguments: Any) -> Any:
        self.rename_calls += 1
        result = self.api.SetFileInformationByHandle(*arguments)
        if not result:
            self.failed("rename")
        else:
            self.rename_returned = True
        return result

    def close_handle(self, handle: int) -> Any:
        self.closes += 1
        result = self.api.CloseHandle(handle)
        if result:
            self.handles.discard(int(handle))
        else:
            self.failed("close")
        return result

    def failed(self, operation: str) -> None:
        if self.first_failed_operation is None:
            self.first_failed_operation = operation

    def report(self) -> dict[str, object]:
        return {
            "opens": self.opens,
            "closes": self.closes,
            "rename_calls": self.rename_calls,
            "rename_returned": self.rename_returned,
            "owned_handles_remaining": len(self.handles),
            "first_failed_operation": self.first_failed_operation,
        }


class _RenameOs:
    def __init__(self, original: Any, probe: Any):
        self.original = original
        self.probe = probe
        self.expected = None
        self.snapshot_taken = False
        self.snapshot_failure: BaseException | None = None

    def __getattr__(self, name: str) -> Any:
        return getattr(self.original, name)

    def close(self, descriptor: int) -> None:
        # Observation failure is re-raised unchanged at the next replace seam,
        # after the original close and its descriptor = -1 state transition.
        # This avoids causing the writer's finally to close the same fd twice.
        try:
            self.expected = self.probe.snapshot_descriptor(descriptor)
            self.snapshot_taken = True
        except BaseException as error:
            self.snapshot_failure = error
        self.original.close(descriptor)

    def replace(self, source: Path, destination: Path) -> None:
        if self.snapshot_failure is not None:
            raise self.snapshot_failure
        if self.expected is None:
            raise RuntimeError("probe_original_writer_snapshot_missing")
        self.probe.replace_once(Path(source), Path(destination), self.expected)


def _writer(args: Any, original_child: Any, probe: Any, native: _NativeCalls) -> int:
    from codex_plugin_scanner.guard.daemon import manager

    original_os = manager.os
    observer = _RenameOs(original_os, probe)
    original_print = getattr(original_child, "print", print)

    def report_print(value: str, **keywords: Any) -> None:
        report = json.loads(value)
        report["probe"] = native.report()
        report["probe"]["writer_snapshot_taken"] = observer.snapshot_taken
        original_print(json.dumps(report, sort_keys=True), **keywords)

    manager.os = cast(Any, observer)
    original_child.print = report_print
    try:
        return original_child._writer(args)
    finally:
        manager.os = original_os
        original_child.print = original_print


def _audit(args: Any, original_child: Any, probe: Any, native: _NativeCalls) -> int:
    source = args.target.with_name(".rename-audit-source")
    descriptor = os.open(source, os.O_RDONLY)
    try:
        expected = probe.snapshot_descriptor(descriptor)
    finally:
        os.close(descriptor)
    refusal = RuntimeError("synthetic rename audit refusal")
    events: list[dict[str, object]] = []
    observed = None

    def audit(event: str, arguments: tuple[object, ...]) -> None:
        if event != "os.rename":
            return
        events.append(
            {
                "source_same": arguments[0] == str(source),
                "destination_same": arguments[1] == str(args.target),
                "source_dir_fd": arguments[2],
                "destination_dir_fd": arguments[3],
                "opens_before_event": native.opens,
                "renames_before_event": native.rename_calls,
            }
        )
        if args.refuse:
            raise refusal

    sys.addaudithook(audit)
    try:
        if args.candidate:
            probe.replace_once(source, args.target, expected)
        else:
            os.replace(source, args.target)
    except BaseException as error:
        observed = error
    print(
        json.dumps(
            {
                "schema": 1,
                "operation": "rename_audit",
                "events": events,
                "refusal_same_object": observed is refusal,
                "error": original_child._code(observed),
                "probe": native.report(),
            },
            sort_keys=True,
        ),
        flush=True,
    )
    return 0


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source-root", type=Path, required=True)
    parser.add_argument("--target", type=Path, required=True)
    parser.add_argument("--operation", choices=("writer", "rename_audit"), required=True)
    parser.add_argument("--hold-crt-source", action="store_true")
    parser.add_argument("--candidate", action="store_true")
    parser.add_argument("--refuse", action="store_true")
    args = parser.parse_args()
    if os.name != "nt" or sys.flags.isolated != 1:
        raise RuntimeError("probe_requires_isolated_windows_python")
    source = args.source_root.resolve(strict=True)
    sys.path[:0] = [str(source / "src"), str(source)]
    from ci.native_runtime import windows_atomic_rename_probe as probe
    from ci.native_runtime import windows_replaceable_reader_child as original_child

    native = _NativeCalls(probe._api())
    probe._api = lambda: native
    try:
        if args.operation == "writer":
            return _writer(args, original_child, probe, native)
        return _audit(args, original_child, probe, native)
    except BaseException as error:
        print(
            json.dumps(
                {
                    "schema": 1,
                    "operation": "failure",
                    "requested_operation": args.operation,
                    "error": original_child._code(error),
                    "probe": native.report(),
                },
                sort_keys=True,
            ),
            flush=True,
        )
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
